import { loadFont as loadDisplay } from "@remotion/google-fonts/Fraunces";
import React, { forwardRef, useId, useImperativeHandle, useMemo, useRef, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// The orb drifts in beside the title, then a sheet of fluted glass sweeps
// across the frame and leaves the scene sharp. Frames on the 30 fps scene
// timeline, after `delay` and `speed`. The ids are public: a saved `timing`
// prop refers to them.

type FlutedGlassElementId = "orb" | "sweep";

interface FlutedGlassTimingProps {
  sweep?: number;
}

const flutedGlassTimeline = defineTimeline<
  FlutedGlassElementId,
  FlutedGlassTimingProps
>(({ sweep = 46 }) => [
  { id: "orb", lane: "Orb", label: "orb drifts in", start: 0, length: 62 },
  {
    id: "sweep",
    lane: "Glass",
    label: "glass sweeps",
    start: 66,
    length: sweep,
  },
]);

const { fontFamily: display } = loadDisplay("normal", {
  weights: ["400"],
  subsets: ["latin"],
});

interface FlutedGlassProps {
  title?: string;
  accent?: string;
  /** Width of one flute, in px at 720p. */
  fluteWidth?: number;
  /** Frames the glass takes to slide across the frame. */
  sweep?: number;
  /** Color of the title; overrides the theme ink. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the title. Load it yourself; Fraunces by default. */
  fontFamily?: string;
  /** Size of the orb, title and glass, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  /** Film grain over the scene. */
  grain?: boolean;
  theme?: "dark" | "light";
  speed?: number;
  /**
   * Moves, trims or stretches the orb's drift and the glass sweep, by the ids
   * in `./timeline`. Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<FlutedGlassElementId>;
}

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "fluted" palette: bg #050507, [#1d2a8f, #2f7bff, #ff7a3d, #ffe2c4].
// It fills the disc only, so the flutes have colour to refract.
const FLUTED = ["#1d2a8f", "#2f7bff", "#ff7a3d", "#ffe2c4"] as const;

const THEMES = {
  dark: {
    bg: "#050507",
    fg: "#F3F2EF",
    tint: "rgba(255,255,255,0.025)",
    ridge: "rgba(255,255,255,0.13)",
    spec: "rgba(255,255,255,0.2)",
    valley: "rgba(0,0,0,0.42)",
    sheen: "rgba(255,255,255,0.05)",
    edge: "rgba(255,255,255,0.55)",
    contact: "rgba(0,0,0,0.5)",
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    tint: "rgba(255,255,255,0.22)",
    ridge: "rgba(255,255,255,0.75)",
    spec: "rgba(255,255,255,0.9)",
    valley: "rgba(70,62,48,0.2)",
    sheen: "rgba(255,255,255,0.3)",
    edge: "rgba(255,255,255,1)",
    contact: "rgba(70,62,48,0.2)",
    grain: 0.045,
  },
} as const;

type Palette = (typeof THEMES)[keyof typeof THEMES];

// Rough Fraunces 400 advances, only used to pick a font size that fits;
// the row itself is laid out by flexbox so the estimate never shifts it.
function textWidth(s: string, size: number) {
  let w = 0;
  for (const ch of s) {
    if (ch === " ") w += 0.25;
    else if ("iljtfr,.;:!'|".includes(ch)) w += 0.32;
    else if ("mwMW".includes(ch)) w += 0.86;
    else if (ch >= "A" && ch <= "Z") w += 0.68;
    else if (ch >= "0" && ch <= "9") w += 0.6;
    else w += 0.54;
    w -= 0.025;
  }
  return w * size;
}

function hash(n: number) {
  const x = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return x - Math.floor(x);
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={21}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

interface Layout {
  u: number;
  size: number;
  disc: number;
  gap: number;
}

function useLayout(title: string): Layout {
  const { width, height } = useSceneConfig();
  const u = height / 720;
  const disc = height * 0.42;
  const gap = 60 * u;
  const room = width * 0.84 - disc - gap;
  const size = Math.min(170 * u, room / Math.max(textWidth(title, 1), 0.1));
  return { u, size, disc, gap };
}

function Backdrop({
  t,
  orbStart,
  orbEnd,
  title,
  accent,
  L,
  fg,
  bg,
  fontFamily,
}: {
  t: number;
  /** Frames the orb drifts in between. */
  orbStart: number;
  orbEnd: number;
  title: string;
  accent: string;
  p: Palette;
  L: Layout;
  fg: string;
  bg: string;
  fontFamily: string;
}) {
  const { width, height } = useSceneConfig();
  const drift = EASE_IO(interpolate(t, [orbStart, orbEnd], [0, 1], CLAMP));
  const ox = -width * 0.34 * (1 - drift);
  const oy = Math.sin(drift * Math.PI) * -46 * L.u;
  const angle = 168 + 10 * Math.sin(t / 44);
  return (
    <div
      style={{
        position: "absolute",
        left: 0,
        top: 0,
        width,
        height,
        background: bg,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          position: "relative",
          flex: "none",
          width: L.disc,
          height: L.disc,
          marginRight: L.gap,
        }}
      >
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: `translate(${ox}px, ${oy}px)`,
            borderRadius: "50%",
            background: `linear-gradient(${angle}deg, ${FLUTED[3]} 2%, ${FLUTED[2]} 30%, color-mix(in oklab, ${FLUTED[2]} 35%, ${FLUTED[1]}) 50%, ${FLUTED[1]} 70%, ${FLUTED[0]} 100%)`,
            boxShadow: `inset 0 0 0 ${1 * L.u}px color-mix(in oklab, ${accent} 30%, transparent)`,
          }}
        />
      </div>
      <div
        style={{
          flex: "none",
          fontFamily,
          fontWeight: 400,
          fontSize: L.size,
          letterSpacing: "-0.035em",
          lineHeight: 1,
          color: fg,
          whiteSpace: "pre",
          paddingBottom: L.size * 0.06,
        }}
      >
        {title}
      </div>
    </div>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function FlutedGlassBase(props: FlutedGlassProps) {
  const {
    title = "In focus.",
    accent = "#3B5BFD",
    fluteWidth = 26,
    ink,
    background,
    fontFamily = display,
    scale = 1,
    delay = 0,
    grain = true,
    theme = "dark",
    speed = 1,
    timing,
  } = props;
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width, height, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    flutedGlassTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const orb = tl.get("orb");
  const sweep = tl.get("sweep");
  const p = THEMES[theme];
  const fg = ink ?? p.fg;
  const bg =
    background === "transparent" ? "transparent" : (background ?? p.bg);
  const L = useLayout(title);
  const { u } = L;

  const fw = Math.max(1, fluteWidth) * u;
  const lens = 0.3;
  const travel = width + 90 * u;
  const slideAt = (f: number) =>
    EASE_IO(interpolate(f, [sweep.start, sweep.end], [0, 1], CLAMP)) * travel;
  const gx = slideAt(t);
  const vel = (gx - slideAt(t - 1)) / u;
  const smear = interpolate(vel, [8, 40], [0, 5], CLAMP) * u;

  // Layout rounds a box edge to whole pixels, so a sheet slid by `left` steps
  // unevenly; it is laid out at its resting place and slides by transform.
  const slide = gx === 0 ? undefined : `translateX(${gx}px)`;

  const flutes: number[] = [];
  for (let i = 0; gx + i * fw < width; i++) flutes.push(i);

  const scene = {
    t,
    orbStart: orb.start,
    orbEnd: orb.end,
    title,
    accent,
    p,
    L,
    fg,
    bg,
    fontFamily,
  };

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>
        <Backdrop {...scene} />
        {gx < width ? (
          <div
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              width: width + fw,
              height,
              transform: slide,
              boxShadow: `${-18 * u}px 0 ${40 * u}px ${-6 * u}px ${p.contact}`,
            }}
          />
        ) : null}
        <div
          style={{
            position: "absolute",
            inset: 0,
            filter: `blur(${1.4 * u + smear}px)`,
          }}
        >
          {flutes.map((i) => {
            const x0 = gx + i * fw;
            const wobble = (hash(i) - 0.5) * 3 * u;
            return (
              <div
                key={i}
                style={{
                  position: "absolute",
                  left: x0,
                  top: 0,
                  width: fw + 0.6,
                  height,
                  overflow: "hidden",
                }}
              >
                <div
                  style={{
                    position: "absolute",
                    left: -x0,
                    top: 0,
                    width,
                    height,
                    transform: `scaleX(${-lens})`,
                    transformOrigin: `${x0 + fw / 2 + wobble}px 50%`,
                  }}
                >
                  <Backdrop {...scene} />
                </div>
              </div>
            );
          })}
        </div>
        {gx < width ? (
          <div
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              // Ends on the frame's right edge, as `right: 0` did.
              width: width - gx,
              bottom: 0,
              transform: slide,
              filter: smear > 0.3 ? `blur(${smear}px)` : undefined,
            }}
          >
            <div
              style={{
                position: "absolute",
                inset: 0,
                background: p.tint,
              }}
            />
            <div
              style={{
                position: "absolute",
                inset: 0,
                backgroundImage: `linear-gradient(90deg, ${p.ridge} 0, rgba(0,0,0,0) ${fw * 0.1}px, rgba(0,0,0,0) ${fw * 0.2}px, ${p.spec} ${fw * 0.27}px, rgba(0,0,0,0) ${fw * 0.4}px, rgba(0,0,0,0) ${fw * 0.62}px, ${p.valley} ${fw}px)`,
                backgroundSize: `${fw}px 100%`,
                opacity: 0.85,
              }}
            />
            <div
              style={{
                position: "absolute",
                inset: 0,
                background: `linear-gradient(180deg, ${p.sheen}, rgba(0,0,0,0) 45%, rgba(0,0,0,0) 70%, ${p.sheen})`,
              }}
            />
            <div
              style={{
                position: "absolute",
                left: 0,
                top: 0,
                bottom: 0,
                width: 7 * u,
                background: `linear-gradient(90deg, ${p.edge}, rgba(255,255,255,0.08) 45%, rgba(0,0,0,0) 100%)`,
                opacity: gx > 0 ? 1 : 0,
              }}
            />
          </div>
        ) : null}
      </ScaleLayer>
      {grain ? <Grain opacity={p.grain} /> : null}
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  title: {
    type: "text-content",
    default: "In focus.",
    description: "Title",
  },
  fluteWidth: {
    type: "number",
    default: 26,
    min: 10,
    max: 80,
    step: 1,
    description: "Flute width",
    hiddenFromList: false,
  },
  sweep: {
    type: "number",
    default: 46,
    min: 16,
    max: 120,
    step: 2,
    description: "Sweep (frames)",
    hiddenFromList: false,
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  fontFamily: {
    type: "font-family",
    default: "Fraunces",
    description: "Font",
  },
  ink: {
    type: "color",
    default: undefined,
    description: "Text color",
  },
  background: {
    type: "color",
    default: undefined,
    description: "Background",
  },
  scale: {
    type: "number",
    default: 1,
    min: 0.5,
    max: 1.5,
    step: 0.05,
    description: "Scale",
    hiddenFromList: false,
  },
  delay: {
    type: "number",
    default: 0,
    min: 0,
    max: 60,
    step: 1,
    description: "Delay (frames)",
    hiddenFromList: false,
  },
  grain: {
    type: "boolean",
    default: true,
    description: "Grain",
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","title","fluteWidth","sweep","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  title: "In focus.",
  fluteWidth: 26,
  sweep: 46,
  accent: "#3B5BFD",
  fontFamily: "Fraunces",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type FlutedGlassElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof FlutedGlassBase>;

const FlutedGlassInner = forwardRef<
  HTMLDivElement,
  FlutedGlassElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<FlutedGlass>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <FlutedGlassBase
          {...(componentProps as unknown as ComponentProps<typeof FlutedGlassBase>)}
        />
      </div>
    </Sequence>
  );
});

export const FlutedGlass = Interactive.withSchema({
  Component: FlutedGlassInner,
  componentName: "<FlutedGlass>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
